UPDATE dodo_theme_top_goods_ref
parent_id = #{parentId}, goods_id = #{goodsId}, goods_sn = #{goodsSn}, sort_order = #{sortOrder}, promote_price = #{promotePrice}, limit_per_order = #{limitPerOrder},
