UPDATE dodo_theme_top_goods_ref SET
parent_id = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.parentId}
    ELSE parent_id END,
goods_id = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.goodsId}
    ELSE goods_id END,
goods_sn = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.goodsSn}
    ELSE goods_sn END,
sort_order = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.sortOrder}
    ELSE sort_order END,
promote_price = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.promotePrice}
    ELSE promote_price END,
limit_per_order = CASE
    WHEN id = #{item.id} AND store_id = #{item.storeId} THEN #{item.limitPerOrder}
    ELSE limit_per_order END
WHERE (id = #{item.id} AND store_id = #{item.storeId})
